actions.script:
def org = ec.user.getPreference('ACTIVE_ORGANIZATION')
def uri = ec.web?.request?.requestURI ?: ''
def zenithIndex = uri.indexOf('/zenith/')
kitchenAction = (zenithIndex > 0 ? uri.substring(0, zenithIndex) : '') +
    '/zenith' + kitchenModulePath + '/KitchenDisplay/updateStatus'
kitchenToken = ec.web?.sessionToken ?: ''
displayAdmin=ec.user.isInGroup('ADMIN') || ec.user.isInGroup('ZENITH_ADMIN')
def shopScope=ec.service.sync().name('zenith.base.ShopServices.get#ActiveShopScope').call()
policyShops=shopScope.shopList
def policy=ec.service.sync().name('zenith.pos.KotServices.get#KitchenDisplayPolicy').parameter('facilityId',ec.context.facilityId).call()
policyShopId=policy.shopId ?: ''; kitchenDisplayEnabled=policy.enabled
def kotQuery = ec.entity.find("zenith.erp.pos.KotView")
kotQuery.condition('organizationPartyId', org && org != '_NA_' ? org : '__NO_ORGANIZATION__')
def statuses=['KotNew','KotPreparing','KotReady']
if (!(filterStatus in statuses)) filterStatus=''
def allActive=kotQuery.condition('statusId','in',statuses).orderBy('-kotDate,kotId').list()
def policies=[:]
def terminals=allActive*.terminalId.findAll { it }.unique()
def tableIds=allActive*.tableId.findAll { it }.unique()
def terminalShops=terminals ? ec.entity.find('zenith.erp.pos.PosTerminal').condition('terminalId','in',terminals)
    .condition('organizationPartyId',org).list().collectEntries { [it.terminalId,it.facilityId] } : [:]
def tableShops=tableIds ? ec.entity.find('zenith.erp.pos.RestaurantTable').condition('tableId','in',tableIds)
    .list().collectEntries { [it.tableId,it.facilityId] } : [:]
allActive=allActive.findAll { order ->
    def shopId=terminalShops[order.terminalId] ?: tableShops[order.tableId]
    if(policyShopId && shopId!=policyShopId) return false
    if(!shopId) return true
    if(!policies.containsKey(shopId)) policies[shopId]=ec.service.sync().name('zenith.pos.KotServices.get#KitchenDisplayPolicy').parameter('facilityId',shopId).call().enabled
    return policies[shopId]
}
newCount=allActive.count { it.statusId=='KotNew' }
preparingCount=allActive.count { it.statusId=='KotPreparing' }
readyCount=allActive.count { it.statusId=='KotReady' }
activeKots=filterStatus ? allActive.findAll { it.statusId==filterStatus } : allActive
kotItemsMap=activeKots ? ec.entity.find('zenith.erp.pos.KotItem').condition('kotId','in',activeKots*.kotId)
    .orderBy('kotItemSeqId').list().groupBy { it.kotId } : [:]
kitchenPageUrl=kitchenAction.substring(0,kitchenAction.lastIndexOf('/'))
